function normalized(s) { return s.normalize('NFKC').toLocaleLowerCase('ko').replace(/\s+/g,' ').trim(); }
function matchingTopics(topics,filter) {
  return topics.filter(t=>(filter.industry==='all'||t.industry===filter.industry)&&(!filter.grade||t.grade===filter.grade)&&normalized([t.title,t.question,t.subject,t.principle,...t.compare,...t.points,t.difference,INDUSTRIES.find(i=>i.id===t.industry).name].join(' ')).includes(normalized(filter.q)));
}
